{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Holistic & Integrative Medicine</title>
  <meta name="description" content="Whole-person care, education-forward consultations, events series and mindful rituals in {{CITY}}, {{STATE}}.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="site">
  <header class="site-header">
    <div class="brand">
      <strong class="name">{{BUSINESS_NAME}}</strong>
      <span class="tag">{{TAGLINE}}</span>
    </div>
    <nav class="nav" id="mainNav">
      <button class="nav-toggle" id="navToggle" aria-controls="navList" aria-expanded="false">Menu</button>
      <ul class="nav-list" id="navList">
        <li><a href="services.html">Offerings</a></li>
        <li><a href="conditions.html">Concerns</a></li>
        <li><a href="approach.html">Philosophy</a></li>
        <li><a href="pricing.html">Investment</a></li>
        <li><a href="about.html">Who We Are</a></li>
        <li><a href="book.html" class="cta">{{PRIMARY_CTA_LABEL}}</a></li>
        <li><a href="contact.html">Reach Out</a></li>
      </ul>
    </nav>
  </header>

  <main>
    <section id="hero" class="hero split-diagonal">
      <div class="pane content">
        <h1 class="headline">At the intersection of science and lived experience.</h1>
        <p class="lead">We listen to the whole you — body, mind, rhythm — and craft learning-centered plans that restore balance over time.</p>
        <p class="meta">Join our events series or book a thoughtful intake with {{PRACTITIONER_NAME}}, {{CREDENTIALS}} in {{CITY}}, {{STATE}}.</p>
        <p class="actions">
          <a class="button primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="button ghost" href="#schedule">Upcoming Series</a>
        </p>
      </div>
      <div class="pane pattern" role="img" aria-hidden="true">
        <img src="assets/img/pattern.svg" alt="decorative background"/>
      </div>
    </section>

    <section id="ritual" class="section ritual">
      <div class="wrap">
        <h2>Rituals as medicine</h2>
        <p class="intro">Small, repeatable practices — breath, movement, dietary rhythm, reflective journaling — are tools. We teach how to fold them into daily life so benefits compound.</p>
        <div class="ritual-grid">
          <article>
            <h3>Morning Anchor</h3>
            <p>Five minutes of intentional breathing and easy movement to set a nervous-system tone for the day.</p>
          </article>
          <article>
            <h3>Digestive Pause</h3>
            <p>Mindful eating rituals that support digestion and awareness, taught with practical guidance.</p>
          </article>
          <article>
            <h3>Evening Wind-Down</h3>
            <p>A gentle sequence to lower inflammation-promoting stress and support restorative sleep.</p>
          </article>
        </div>
      </div>
    </section>

    <section id="what-to-expect" class="section what-to-expect">
      <div class="wrap narrow">
        <h2>What to expect</h2>
        <ol>
          <li><strong>Curious intake:</strong> we gather history, lifestyle map, and priorities — education is part of the visit.</li>
          <li><strong>Shared plan:</strong> a practical, layered plan mixing nutrition, movement, mindful practices, and optional labs.</li>
          <li><strong>Follow-ups:</strong> short touchpoints to adjust, measure, and teach new skills so changes stick.</li>
        </ol>
        <p class="disclaimer">We do not promise cures. Our work focuses on education, resilience, and whole-person support. Labs and supplements may be offered as educational options when clinically appropriate.</p>
      </div>
    </section>

    <section id="schedule" class="section schedule">
      <div class="wrap">
        <h2>Events Series & Schedule</h2>
        <p class="lead">A cycle of small-group workshops and guided rituals — learn, practice, and integrate. Spaces are limited.</p>
        <ul class="events" id="eventsList">
          <li data-date="2026-03-06"><strong>Foundations: Rhythm & Rest</strong><span> — 3/6 • 6:30pm — Intro workshop exploring sleep and daily rhythm.</span></li>
          <li data-date="2026-03-13"><strong>Gentle Nutrition for Digestion</strong><span> — 3/13 • 6:30pm — Practical steps to reduce bloating and improve energy.</span></li>
          <li data-date="2026-03-20"><strong>Stress, Breath & Nervous System</strong><span> — 3/20 • 6:30pm — Tools to lower reactivity without medication.</span></li>
        </ul>
        <p class="note">Events are educational and complementary to private care. To reserve a seat, click the reserve button or call <a href="tel:{{PHONE}}">{{PHONE}}</a>.</p>
        <p class="actions"><a class="button" href="book.html">Reserve a Spot</a></p>
      </div>
    </section>

    <section id="pricing" class="section pricing">
      <div class="wrap narrow">
        <h2>Investment & Offers</h2>
        <div class="pricing-grid">
          <div class="tier">
            <h3>Intro Visit</h3>
            <p class="price">$120 — 45 minutes</p>
            <p class="desc">A thorough intake focused on education and rule-in/rule-out priorities.</p>
          </div>
          <div class="tier highlighted">
            <h3>Care Series</h3>
            <p class="price">$400 — 4 sessions</p>
            <p class="desc">A sequence of visits with follow-ups for measurable change and skill-building.</p>
          </div>
          <div class="tier">
            <h3>Workshops</h3>
            <p class="price">$35–$75 each</p>
            <p class="desc">Drop-in educational sessions; sliding scale available for those in need.</p>
          </div>
        </div>
        <p class="disclaimer">All pricing is educational and subject to change. Insurance billing varies; we will provide superbills upon request. Nothing listed is a guaranteed cure.</p>
      </div>
    </section>

    <section id="faq" class="section faq">
      <div class="wrap">
        <h2>Questions people ask</h2>
        <details>
          <summary>Do you treat chronic conditions?</summary>
          <p>We support whole-person strategies that aim to reduce symptoms and improve function through education and lifestyle-based interventions. We do not promise cures; care is individualized and often collaborative.</p>
        </details>
        <details>
          <summary>Will you order labs?</summary>
          <p>Optional labs are discussed as educational tools to guide personalized plans. We explain why a test may be useful and how to interpret results.</p>
        </details>
        <details>
          <summary>How do virtual visits work?</summary>
          <p>Virtual appointments use secure video. Many learning and coaching elements translate well online; some physical assessments may require an in-person visit.</p>
        </details>
      </div>
    </section>

    <section id="cta" class="section cta">
      <div class="wrap split-cta">
        <div>
          <h2>Ready to begin a different kind of care?</h2>
          <p>Schedule a thoughtful intake or join a learning series to start changing habits with support.</p>
        </div>
        <div class="actions">
          <a class="button primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="button ghost" href="contact.html">Contact — {{PHONE}}</a>
        </div>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="wrap footer-grid">
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <p>{{TAGLINE}}</p>
        <p><a href="tel:{{PHONE}}">{{PHONE}}</a> • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      </div>
      <div>
        <h4>Navigate</h4>
        <ul>
          <li><a href="services.html">Offerings</a></li>
          <li><a href="conditions.html">Concerns</a></li>
          <li><a href="approach.html">Philosophy</a></li>
          <li><a href="pricing.html">Investment</a></li>
        </ul>
      </div>
      <div>
        <h4>Address</h4>
        <p>{{CITY}}, {{STATE}}</p>
      </div>
    </div>
    <p class="muted">&copy; <span id="year"></span> {{BUSINESS_NAME}} — All rights reserved. Not a substitute for medical care.</p>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
