{"path":"assets/css/styles.css","content":"/* Minimal poetic UI for holistic practice — split diagonal layout */
:root{
  --bg:#fffdf8;
  --muted:#6b6b6b;
  --accent:#3a6b5a;
  --accent-2:#8fbf9a;
  --glass: rgba(255,255,255,0.6);
  --max-width:1100px;
  --radius:12px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial; background:var(--bg); color:#0b0b0b; line-height:1.45}
.wrap{max-width:var(--max-width);margin:0 auto;padding:48px 20px}
.site-header{display:flex;justify-content:space-between;align-items:center;padding:18px 20px;background:linear-gradient(180deg, rgba(255,255,255,0.6), rgba(255,255,255,0.8));position:sticky;top:0;backdrop-filter: blur(6px);z-index:40}
.brand .name{font-weight:700;letter-spacing:0.6px}
.brand .tag{display:block;font-size:0.9rem;color:var(--muted)}
.nav-list{list-style:none;margin:0;padding:0;display:flex;gap:12px;align-items:center}
.nav-list a{color:inherit;text-decoration:none;padding:8px 10px;border-radius:8px}
.nav-list a.cta{background:var(--accent);color:white}
.nav-toggle{display:none;background:none;border:1px solid transparent;padding:8px}

.hero{display:flex;min-height:60vh;align-items:stretch;overflow:hidden}
.split-diagonal .pane{flex:1;position:relative;padding:48px}
.split-diagonal .content{display:flex;flex-direction:column;justify-content:center;gap:18px}
.headline{font-size:2rem;margin:0;color:var(--accent)}
.lead{color:var(--muted);font-size:1.05rem}
.meta{font-size:0.95rem;color:#42514a}
.actions{display:flex;gap:12px;margin-top:6px}
.button{display:inline-block;padding:10px 16px;border-radius:8px;text-decoration:none;border:1px solid rgba(0,0,0,0.06)}
.button.primary{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:white}
.button.ghost{background:transparent;border:1px solid rgba(0,0,0,0.06)}

.pane.pattern{display:flex;align-items:center;justify-content:center;background:linear-gradient(135deg,#f6fbf8 0%, #ecf6f2 100%);}
.pane.pattern img{width:100%;height:100%;object-fit:cover;opacity:0.95}

.section{padding:48px 0}
.ritual-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:18px;margin-top:18px}
.ritual-grid article{background:var(--glass);padding:18px;border-radius:12px}
.what-to-expect .narrow{max-width:820px}
.disclaimer{font-size:0.9rem;color:var(--muted);margin-top:10px}

.schedule .events{list-style:none;padding:0;margin:18px 0}
.events li{padding:12px 10px;border-radius:8px;margin-bottom:10px;background:linear-gradient(180deg,#fff 0%, #fbfdfa 100%);display:flex;justify-content:space-between;align-items:center;border:1px solid rgba(0,0,0,0.04)}

.pricing-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px}
.tier{background:linear-gradient(180deg,#fff 0%, #fbfdfa 100%);padding:18px;border-radius:12px;border:1px solid rgba(0,0,0,0.04)}
.tier.highlighted{box-shadow:0 8px 24px rgba(58,107,90,0.08);border-color:rgba(58,107,90,0.12)}
.price{font-weight:700;color:var(--accent);font-size:1.1rem}

.faq details{background:var(--glass);padding:12px;border-radius:10px;margin:8px 0}

.cta .split-cta{display:flex;justify-content:space-between;align-items:center;gap:20px}
.site-footer{border-top:1px solid rgba(0,0,0,0.04);padding:28px 20px;background:linear-gradient(180deg, transparent, rgba(250,250,250,0.6))}
.footer-grid{display:grid;grid-template-columns:1fr 160px 120px;gap:20px}
.muted{color:var(--muted);font-size:0.9rem}

@media (max-width:900px){
  .hero{flex-direction:column}
  .pane.pattern{order:-1;height:220px}
  .nav-list{display:none;flex-direction:column;position:absolute;right:20px;top:60px;background:white;padding:12px;border-radius:8px;box-shadow:0 8px 20px rgba(0,0,0,0.08)}
  .nav-toggle{display:inline-block}
  .footer-grid{grid-template-columns:1fr}
  .cta .split-cta{flex-direction:column;align-items:flex-start}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // simple interactivity: mobile nav toggle, smooth scroll, current year
  document.addEventListener('DOMContentLoaded',function(){
    var navToggle = document.getElementById('navToggle');
    var navList = document.getElementById('navList');
    if(navToggle){
      navToggle.addEventListener('click',function(){
        var expanded = this.getAttribute('aria-expanded') === 'true';
        this.setAttribute('aria-expanded', String(!expanded));
        if(navList.style.display === 'flex'){ navList.style.display = 'none'; }
        else{ navList.style.display = 'flex'; navList.style.flexDirection = 'column'; }
      });
    }

    // smooth scroll for in-page links
    document.querySelectorAll('a[href^="#"]').forEach(function(a){
      a.addEventListener('click',function(e){
        var id = this.getAttribute('href').slice(1);
        var el = document.getElementById(id);
        if(el){ e.preventDefault(); el.scrollIntoView({behavior:'smooth',block:'start'}); }
      });
    });

    // attach small interaction for events: highlight next upcoming
    var events = document.querySelectorAll('#eventsList li');
    if(events.length){
      var today = new Date();
      var nextIdx = -1;
      events.forEach(function(li,i){
        var d = li.getAttribute('data-date');
        if(d){
          var dt = new Date(d+'T00:00:00');
          if(nextIdx===-1 && dt >= new Date(today.getFullYear(), today.getMonth(), today.getDate())){ nextIdx = i; }
        }
      });
      if(nextIdx>-1){ events[nextIdx].style.boxShadow = '0 6px 18px rgba(58,107,90,0.08)'; }
    }

    var yearEl = document.getElementById('year');
    if(yearEl) yearEl.textContent = new Date().getFullYear();
  });
})();
"} 
